sys_script_include.script:
function GetActiveHoursRulesForStoreByDate(vStore,vDate)
{
	var RenderDate = x_snc_devtools.RenderDate;
	strDate = RenderDate(vDate);

	var aRules = GetAllHoursRulesForStore(vStore);
	if (aRules === false)
	{
		return false;
	}

	var aActiveRules = [];

	for (var nRule = 0; nRule < aRules.length; nRule++)
	{
		var rule = aRules[nRule];

		if (rule.active == true)
		{
			var strActivationStartDate = rule.activation_start_date;
			if (strActivationStartDate != '')
			{
				if (strActivationStartDate <= strDate)
				{
					var strActivationEndDate = rule.activation_end_date;
					if (strActivationEndDate == '' || (strDate < strActivationEndDate) )
					{
						delete rule.active;
						aActiveRules.push(rule);
					}
				}
			}
		} 
	}

	return aActiveRules;
}
